"""Snap span times to a fixed step for payroll."""

from hourglass.parsing import format_span
from hourglass.models import Span


def snap_minute(minute: int, step: int) -> int:
    """Round to the nearest step, halves going up."""
    return (2 * minute + step) // (2 * step) * step


def check_step(step: int) -> None:
    if step <= 0 or 60 % step:
        raise ValueError(f"bad step: {step!r}")


def round_label(span: Span, step: int) -> str:
    """Label such as 09:00-17:15 (8h 15m), after rounding."""
    start = snap_minute(span.start, step)
    end = snap_minute(span.end, step)
    hours, rest = divmod(end - start, 60)
    text = format_span(Span(start, end))
    return f"{text} ({hours}h {rest:02d}m)"


def round_spans(spans: list, step: int) -> list:
    """Return one label per span, rounded to step minutes."""
    check_step(step)
    return [round_label(item, step) for item in spans]

