import unittest

from hourglass.rounding import round_spans
from hourglass.models import Span


class RoundingTests(unittest.TestCase):
    def test_label(self):
        spans = [Span(9 * 60 + 2, 17 * 60 + 14)]
        self.assertEqual(
            round_spans(spans, 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_halfway_rounds_up(self):
        spans = [Span(5, 25)]
        self.assertEqual(
            round_spans(spans, 10), ["00:10-00:30 (0h 20m)"]
        )

    def test_empty(self):
        self.assertEqual(round_spans([], 5), [])

    def test_bad_steps(self):
        for step in (0, -5, 7, 45, 90):
            with self.assertRaises(ValueError):
                round_spans([], step)
